//! Generates the Rust for each model's graph into `src/models/` and writes its weights beside the sources.
//! Run through `dev/ml-models`, which fetches and converts the ONNX files first.
//!
//!     sidecar-ml-import <dir>     reads <dir>/src/<model>.onnx, writes <dir>/<model>.bpk

use anyhow::{Context, Result, ensure};
use std::path::Path;

/// The version pinned in Cargo.toml, named in each generated file's header.
const BURN_ONNX: &str = "0.22.0-pre.4";

/// Each model, the licence its graph and weights are under, and where it came from.
const MODELS: [(&str, &str, &str); 3] = [
    ("yunet", "MIT", "YuNet face detector (2023mar), OpenCV Zoo"),
    (
        "birefnet",
        "MIT",
        "BiRefNet lite, onnx-community export, simplified at 1024x1024",
    ),
    (
        "multiclass",
        "Apache-2.0",
        "MediaPipe multi-class selfie segmentation 256x256, TFLite converted by tf2onnx",
    ),
];

fn main() -> Result<()> {
    let dir = std::env::args()
        .nth(1)
        .context("usage: sidecar-ml-import <dir>")?;
    let dir = Path::new(&dir);
    let generated = dir.join("generated");
    let mut model_gen = burn_onnx::ModelGen::new();
    for (name, ..) in MODELS {
        let onnx = dir.join("src").join(format!("{name}.onnx"));
        ensure!(
            onnx.is_file(),
            "{} is missing; run dev/ml-models",
            onnx.display()
        );
        model_gen.input(onnx.to_str().context("model path is not UTF-8")?);
    }
    model_gen
        .out_dir(generated.to_str().context("output path is not UTF-8")?)
        .run_from_cli();

    let models = Path::new(env!("CARGO_MANIFEST_DIR")).join("src/models");
    for (name, licence, origin) in MODELS {
        let code = std::fs::read_to_string(generated.join(format!("{name}.rs")))?;
        let header = format!(
            "// SPDX-License-Identifier: {licence}\n// Generated by burn-onnx {BURN_ONNX} from {origin}. Do not edit: rerun dev/ml-models.\n"
        );
        // Only when it changed: rewriting identical code would still make cargo recompile it (minutes, for
        // BiRefNet) in the image build.
        let path = models.join(format!("{name}.rs"));
        let code = header + &code;
        if std::fs::read_to_string(&path).ok().as_deref() != Some(code.as_str()) {
            std::fs::write(&path, code)?;
        }
        reproducible(&generated.join(format!("{name}.bpk")), &dir.join(format!("{name}.bpk")))?;
        println!(
            "{name}: src/models/{name}.rs, {}",
            dir.join(format!("{name}.bpk")).display()
        );
    }
    std::fs::remove_dir_all(generated)?;
    Ok(())
}

/// Copies weights from `from` to `to` without the random `param_id` burn gives each parameter when a model is
/// built. It identifies training state and inference never reads it, but it made every import write different
/// bytes from the same model, so the `-ml` image's weights layer never came out the same twice.
fn reproducible(from: &Path, to: &Path) -> Result<()> {
    let reader = burn_pack::Reader::from_file(from).map_err(|e| anyhow::anyhow!("reading {}: {e:?}", from.display()))?;
    let metadata = reader.metadata().clone();
    let mut tensors = reader.into_tensors().map_err(|e| anyhow::anyhow!("reading {}: {e:?}", from.display()))?;
    tensors.iter_mut().for_each(|t| t.param_id = None);
    let writer = metadata.iter().fold(burn_pack::Writer::new(tensors), |w, (k, v)| w.with_metadata(k, v));
    writer.write_to_file(to).map_err(|e| anyhow::anyhow!("writing {}: {e:?}", to.display()))?;
    Ok(())
}
